alter table public.gst_document_snapshots_v520 add column if not exists document_number text,add column if not exists document_identity_hash text;
create or replace function private.gst_legal_document_number_v520(p_tenant_id uuid,p_source_type text,p_source_id uuid) returns text language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_number text;begin if p_source_type='sale' then select coalesce(dn.terminal_number,ln.local_number) into v_number from public.sales s left join public.device_document_numbers dn on dn.tenant_id=s.tenant_id and dn.entity_type='sale' and dn.entity_id=s.id left join public.location_document_numbers ln on ln.tenant_id=s.tenant_id and ln.entity_type='sale' and ln.entity_id=s.id where s.tenant_id=p_tenant_id and s.id=p_source_id and s.status='posted';elsif p_source_type='purchase' then select nullif(trim(p.supplier_invoice_number),'') into v_number from public.purchases p where p.tenant_id=p_tenant_id and p.id=p_source_id and p.status='posted';elsif p_source_type='purchase_invoice_v484' then select nullif(trim(p.supplier_invoice_number),'') into v_number from public.purchase_invoices_v484 p where p.tenant_id=p_tenant_id and p.id=p_source_id and p.status not in('draft','void');elsif p_source_type='sales_return' then select r.return_number into v_number from public.sales_returns r where r.tenant_id=p_tenant_id and r.id=p_source_id;elsif p_source_type='purchase_return' then select r.return_number into v_number from public.purchase_returns r where r.tenant_id=p_tenant_id and r.id=p_source_id;else raise exception 'Legal GST document number is not enabled for source type %',p_source_type;end if;v_number:=nullif(trim(coalesce(v_number,'')),'');if v_number is null then raise exception 'Legal GST document number is missing for % %',p_source_type,p_source_id;end if;return v_number;end $$;
create or replace function private.gst_snapshot_legal_identity_before_insert_v520() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$ begin new.document_number:=private.gst_legal_document_number_v520(new.tenant_id,new.source_type,new.source_id);new.document_identity_hash:=encode(extensions.digest(convert_to(jsonb_build_object('tenant_id',new.tenant_id,'source_type',new.source_type,'source_id',new.source_id,'source_number',new.source_number,'document_number',new.document_number,'document_date',new.document_date,'thq_registration_id',new.thq_registration_id,'snapshot_hash',new.snapshot_hash)::text,'UTF8'),'sha256'),'hex');return new;end $$;
drop trigger if exists trg_gst_snapshot_legal_identity_v520 on public.gst_document_snapshots_v520;
create trigger trg_gst_snapshot_legal_identity_v520 before insert on public.gst_document_snapshots_v520 for each row execute function private.gst_snapshot_legal_identity_before_insert_v520();
do $$ begin if exists(select 1 from public.gst_document_snapshots_v520 where document_number is null or document_identity_hash is null) then raise exception 'Existing authoritative GST snapshots are missing legal document identity';end if;end $$;
alter table public.gst_document_snapshots_v520 alter column document_number set not null,alter column document_identity_hash set not null;
create unique index if not exists ux_gst_snapshot_outward_document_number_v520 on public.gst_document_snapshots_v520(tenant_id,thq_registration_id,document_number) where direction='outward';
revoke all on function private.gst_legal_document_number_v520(uuid,text,uuid) from public,anon,authenticated;
revoke all on function private.gst_snapshot_legal_identity_before_insert_v520() from public,anon,authenticated;
grant execute on function private.gst_legal_document_number_v520(uuid,text,uuid) to service_role;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(239,'5.2.0-foundation','GST Legal Document Identity','Separates internal THQ source_number from the legal GST document_number, derives legal numbers server-side from terminal/location invoice numbering or supplier invoice references, binds them to an immutable SHA-256 identity hash, and enforces outward document-number uniqueness per GST registration.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;